const PUMPKING_HYDREIGON_ROADMAP={"id":"tyranitar-hydreigon-weezing","title":"Hydreigon boosté · stratégie historique détaillée","status":"Ancienne rotation (2023) archivée dans le compendium ; adaptation à Trick-or-Treat 2025 non démontrée","source":"https://www.scribd.com/document/951571951/Pumpking-Hard-Mode-Strategy-Compendium","sourceSupplement":"https://www.reddit.com/r/pokemmo/comments/1f9s3yv","year":"2023 / 2024 — repère stratégique, NON validé 2025","intro":"Lonely : trois Pokémon sur le terrain. L’ordre initial du guide est Tyranitar à gauche, Hydreigon au centre, Weezing à droite, avec Krookodile sur le Schooling.","roster":[{"name":"Tyranitar","slot":"Gauche · départ","item":"Choice Band","ability":"Sand Stream","nature":"Adamant","ev":"252 Att / 240 Vit / 16 Déf (repère 2024)","iv":"31 Att / 31 Vit conseillés","moves":"Assurance / Crunch / Taunt","note":"Boosts via objets X sur Hydreigon et Assurance. L’ordre de Vitesse avec Weezing compte."},{"name":"Hydreigon","slot":"Centre · départ","item":"Choice Specs","ability":"Levitate","nature":"Modest","ev":"252 Sp. Atk / 76 Vit / 180 Déf (variante historique ; autre proposition 252 AS / 252 Vit)","iv":"31 Sp. Atk / 31 Vit, bulk élevé conseillé","moves":"Snarl / Dark Pulse","note":"Attaquant principal. La répartition 76 Vit dépend du 31 IV Vitesse et de la variante : ne pas changer sans revérifier les seuils."},{"name":"Weezing","slot":"Droite · départ","item":"Leftovers","ability":"Neutralizing Gas","nature":"Bold","ev":"252 HP / 252 Vit (repère 2024)","iv":"HP / Vit / Déf à privilégier","moves":"Taunt / Psywave","note":"Soutien et contrôle du sommeil ; le guide ancien repose sur un comportement de talent pouvant évoluer avec les mises à jour."},{"name":"Krookodile","slot":"Banc · premier remplaçant","item":"Soft Sand","ability":"Moxie","nature":"Adamant (proposition)","ev":"252 Att / 252 Vit (proposition de préparation)","iv":"31 Att / 31 Vit conseillés","moves":"Crunch / Assurance / Earthquake","note":"Finisseur conditionnel après les changements forcés ; ne pas lancer Earthquake sans vérifier les alliés."}],"additional":[{"name":"Honchkrow","role":"Option de réserve historique : Sucker Punch / Assurance ; pas inclus dans la rotation de base"},{"name":"Chandelure","role":"Option de réserve historique : Shadow Ball / Hex ; pas inclus dans la rotation de base"}],"phases":[{"name":"Phase 1","intro":"Contrôler les renforts avec Snarl et garder Hydreigon en état d’attaquer.","steps":[{"title":"Ouverture","slots":["Tyranitar · Spécial + sur Hydreigon","Hydreigon · Snarl","Weezing · Taunt"],"tip":"Attirer le boss vers Tyranitar et empêcher certains effets des renforts. Surveiller les attaques prioritaires de Pumpreaper et Lil’ Pump."},{"title":"Deuxième tour","slots":["Tyranitar · Assurance","Hydreigon · Snarl","Weezing · Psywave ou Recover"],"tip":"Si Hydreigon a perdu les Choice Specs, son STAB ou un niveau d'Att. Spé., renforcer à nouveau son Attaque Spéciale au lieu de suivre aveuglément la ligne."},{"title":"Tours suivants · adaptation","slots":["Tyranitar · Assurance / Spécial + selon l’état","Hydreigon · Snarl sur les renforts","Weezing · Psywave, Taunt ou Recover"],"tip":"Ne pas arrêter de contrôler les renforts trop tôt ; une fois les PV du boss suffisamment bas, ils peuvent privilégier Heal Pulse. Préparer les PV pour la phase suivante."}]},{"name":"Phase 2","intro":"Faire Inner Focus au sommeil. Les objets de Awakening et Taunt priment sur les dégâts si plusieurs Pokémon sont endormis.","steps":[{"title":"Ouverture","slots":["Tyranitar · Spécial + sur Hydreigon","Hydreigon · Snarl","Weezing · X Accuracy"],"tip":"Préparer les boosts avant le tour de sommeil. La source historique prévoit cet objet même si les seuils exacts dépendent du combat."},{"title":"Tour 2 · 0 ou 1 Pokémon endormi","slots":["Tyranitar · Assurance","Hydreigon · Snarl","Weezing · Psywave / Recover"],"tip":"Branche possible seulement si l’équipe peut effectivement agir ; guérir tout Pokémon clé immobilisé avant le prochain risque de changement forcé."},{"title":"Tour 2 · 2 ou 3 Pokémon endormis","slots":["Tyranitar · Awakening / Full Restore totale sur Hydreigon","Hydreigon · Awakening / Full Restore totale sur Weezing","Weezing · Taunt"],"tip":"Priorité au Awakening. La source signale une forte probabilité de permutation forcée lorsque plusieurs Pokémon dorment."},{"title":"Tours suivants · surveiller les renforts","slots":["Tyranitar · Assurance ou Recover","Hydreigon · Snarl ; traiter les renforts","Weezing · Taunt / Psywave / Recover"],"tip":"Utiliser les soins ordinaires avant les cookies lorsqu’ils suffisent. Le cookie Fantôme n’est indiqué que dans certains cas de double sommeil. Garder assez de PV pour la troisième phase."}]},{"name":"Phase 3","intro":"Les objets X et les cookies sont déterminants. Après l'attaque Faux de Pumpking, les remplacements rendent la rotation conditionnelle.","steps":[{"title":"Ouverture","slots":["Tyranitar · Spécial + sur Hydreigon","Hydreigon · Snarl","Weezing · Spécial + sur Hydreigon"],"tip":"Double augmentation de l’Attaque Spéciale de Hydreigon ; Pumpking Tackle ses visions."},{"title":"Deuxième tour","slots":["Tyranitar · Assurance","Hydreigon · Snarl","Weezing · Cookie Balai"],"tip":"Le Cookie Balai protège selon la mécanique de Visions Fantomatiques. Vérifier les effets actifs."},{"title":"Troisième tour · attaque Faux","slots":["Tyranitar · Cookie Chat","Hydreigon · Snarl","Weezing · Max Potion sur Hydreigon"],"tip":"Weezing peut être mis K.O., Tyranitar peut survivre selon le renfort. Après les changements forcés, sélectionner la branche correspondante."},{"title":"Suite A · Krookodile / Tyranitar / Hydreigon","slots":["Krookodile · Crunch / Assurance / X Attack","Tyranitar · Assurance","Hydreigon · Dark Pulse"],"tip":"Meilleur cas décrit par le compendium. Le choix de Krookodile dépend de sa Vitesse et des PV du boss."},{"title":"Suite B · Remplaçant / Tyranitar / Hydreigon","slots":["Remplaçant · X Attack sur Tyranitar","Tyranitar · Assurance","Hydreigon · Dark Pulse"],"tip":"Si Tyranitar est mis K.O. avant la fin, faire entrer Krookodile et réévaluer Earthquake en présence de renforts."},{"title":"Suite C · Remplaçant / Krookodile / Hydreigon","slots":["Remplaçant · Spécial + sur Hydreigon","Krookodile · Crunch / Assurance","Hydreigon · Dark Pulse"],"tip":"Le boss peut utiliser Faux et retirer des boosts. Au tour suivant, envisager Cookie Balai / Earthquake / X Attack."},{"title":"Suite D · Krookodile latéral / Remplaçant / Hydreigon","slots":["Krookodile · Crunch / autre action","Remplaçant · soutien ou Cookie Balai","Hydreigon · Dark Pulse"],"tip":"Earthquake de Krookodile ne touche pas forcément les deux renforts depuis le côté ; cibler celui qui subsiste si Pumpking ne peut pas être terminé."},{"title":"Suite E · deux remplaçants / Krookodile","slots":["Remplaçant · X Attack sur Krookodile","Remplaçant · X Attack / changement","Krookodile · Crunch"],"tip":"Exception : faire entrer Krookodile plutôt que Hydreigon quand les autres positions sont des remplaçants. Si une place se libère, tenter de faire revenir Hydreigon ; sinon réévaluer Earthquake."}]}],"alerts":["Cette feuille de route provient d’une version historique, pas d’un run 2025 vérifié. L’édition 2025 et les changements en cours d’événement peuvent modifier les timings.","Les branches des phases 2 et 3 sont conditionnelles : utiliser le tableau comme aide-mémoire, pas comme suite automatique.","Certains renforts affectent les objets et les caractéristiques, et les coups critiques peuvent imposer des soins supplémentaires.","Pour le mode facile, le compendium indique que les équipes du difficile peuvent aussi fonctionner, sans preuve que chaque séquence ci-dessous reste identique."],"consumables":["Bonbon Spécial","Spécial +","X Accuracy","X Attack","Awakening / Full Restore totale","Max Potion","Cookie Balai","Cookie Chat","Cookie Fantôme (selon sommeil)"]};
const PUMPKING_EASY_ROADMAP={"id":"turtle-wide-guard","title":"Aerodactyl / Krookodile · contrôle et Earthquake","status":"Mode facile : adaptation d'une stratégie difficile historique 2023 (Turtle / Rumel). NON validée en combat Trick-or-Treat 2025 ; version facile dédiée disponible en vidéo 2024.","source":"https://www.youtube.com/watch?v=2d8yXkMHjXQ","sourceSupplement":"https://www.youtube.com/watch?v=RtwrvQB4HYo","year":"2023-2024 (référence historique, non validation 2025)","intro":"Équipe proposée pour le mode facile : Aerodactyl, Krookodile et Gothitelle au départ ; Tyranitar en réserve. Les quatre Pokémon forment le noyau de la rotation historique Turtle, conçue à l'origine pour le mode difficile ; cette adaptation en mode facile reste à vérifier pour l'édition 2025.","roster":[{"name":"Aerodactyl","slot":"Actif au départ (Garde Large / soutien)","item":"Not specified par la transcription","ability":"Verify with source","nature":"À définir selon la Speed","ev":"À valider","iv":"Speed conseillée, seuil non communiqué","moves":"Wide Guard / Taunt / Tailwind","note":"Wide Guard et Taunt sont les actions de soutien de la source historique. Vérifier les moves et l'ordre de position dans le jeu."},{"name":"Krookodile","slot":"Actif au départ (attaquant central)","item":"Not specified par la transcription","ability":"Verify with source","nature":"Adamant ou Jolly (proposition)","ev":"252 Att / 252 Vit (proposition, non seuil confirmé)","iv":"31 Att / 31 Vit (objectif proposé)","moves":"Earthquake / Assurance / Crunch","note":"Le plan historique repose sur Earthquake de Krookodile. Les dégâts sur les alliés et les renforts doivent être anticipés."},{"name":"Gothitelle","slot":"Actif au départ (contrôle)","item":"Not specified par la transcription","ability":"Verify with source","nature":"À déterminer","ev":"À valider","iv":"À valider","moves":"Taunt / Heal Block","note":"L'ordre des changements de Gothitelle/Tyranitar du guide historique doit être vérifié visuellement."},{"name":"Tyranitar","slot":"Banc (Assurance / Mâchouille)","item":"Not specified par la transcription","ability":"Sand Stream (possible ; vérifier la variante)","nature":"Adamant (proposition)","ev":"252 Att / 252 Vit (proposition)","iv":"31 Att / 31 Vit (objectif)","moves":"Assurance / Crunch","note":"Entre sur le terrain pour les séquences à Assurance ; boosts X Attack en fin de combat."}],"additional":[{"name":"Guide facile 2024 en vidéo","role":"OfficialDarku détaille 4 tours de phase 1, 3 de phase 2 et 3 de phase 3 ; ces actions n'ont pas été transcrites de façon vérifiable."},{"name":"Équipe difficile de substitution","role":"La source communautaire indique qu'une équipe réussissant le mode difficile peut aussi battre le mode facile, sans assurer les mêmes timings."}],"phases":[{"name":"Phase 1 · installer le contrôle","intro":"Source Turtle / Rumel : Reflect de zone avec Wide Guard, Earthquake de Krookodile et Taunt. C'est une transposition vers le mode facile, pas une rotation validée spécifiquement pour 2025.","steps":[{"title":"T1 · Reflect","slots":["Wide Guard","Earthquake","Taunt"],"tip":"Protéger des attaques de zone, limiter les actions adverses, puis attaquer. Les trois commandes suivent l'ordre de la vidéo historique."},{"title":"T2 · pivot","slots":["Déplacer Gothitelle selon le placement","Earthquake","Remplacer Gothitelle par Tyranitar"],"tip":"Le guide ancien demande un déplacement de Gothitelle puis un remplacement. Réévaluer les positions avant de cliquer : aucune localisation de remplacement n'est garantie sur l'édition 2025."},{"title":"T3 · Pressure","slots":["Assurance","Earthquake","Taunt"],"tip":"Assurance bénéficie de l'ordre des attaques ; ne pas reproduire le tour si des renforts ont modifié le placement."},{"title":"T4 · transition","slots":["Soigner les Pokémon touchés","Terminer la phase avec l'attaque disponible","Conserver les Pokémon nécessaires ensuite"],"tip":"La source demande de soigner les blessés avant de terminer ; les trois actions de ce tour sont des intentions, pas une combinaison fixe."}]},{"name":"Phase 2 · bloquer les soins","intro":"Dans la rotation Turtle, Heal Block devient prioritaire au début de la deuxième phase. La difficulté facile n'est pas identique à la difficile : surveiller la survie et éviter de surconsommer les objets.","steps":[{"title":"T1 · Heal Block","slots":["X Attack","Earthquake","Heal Block"],"tip":"Heal Block empêche les soins adverses. Inner Focus : l'action 1 est un objet X Attaque utilisé sur le bon attaquant."},{"title":"T2 · verrouiller le boss","slots":["Taunt","Earthquake","Assurance"],"tip":"Taunt, attaque de zone et Assurance forment le tour de contrôle du guide."},{"title":"T3 · récupérer","slots":["Cookie Citrouille","Earthquake","Revive sur Gothitelle"],"tip":"La source prévoit le Revive de Gothitelle et les soins de groupe ; s'adapter à la présence des renforts."},{"title":"T4 · soigner avant la finale","slots":["Soigner Tyranitar, Krookodile ou Aerodactyl","Earthquake","Ajuster le Recover selon l'état de l'équipe"],"tip":"Ne pas entrer en phase 3 avec les Pokémon essentiels trop affaiblis."}]},{"name":"Phase 3 · préparer le finisseur","intro":"Le dernier segment exige l'utilisation d'objets X, un bonus de Vitesse et Tyranitar comme finisseur, selon une rotation ancienne dont la compatibilité 2025 n'est pas attestée.","steps":[{"title":"T1 · boosts","slots":["X Attack sur Krookodile","Earthquake","Cookie Balai ou Cookie Chauve-Souris sur Gothitelle"],"tip":"Les cookies et les boosts sont propres à cette dernière phase : ne pas recopier les instructions de la phase 1."},{"title":"T2 · vitesse","slots":["Tailwind","Earthquake","Assurance"],"tip":"Tailwind modifie la Vitesse ; prendre en compte la possibilité de renforts rapides."},{"title":"T3 · renforcer Tyranitar","slots":["X Attack sur Tyranitar","Earthquake","Assurance"],"tip":"Renforcer le finisseur. Si des K.O. perturbent les positions, adapter plutôt que forcer la rotation."},{"title":"T4 · terminer","slots":["X Attack sur Tyranitar","Crunch / attaque finale selon le placement","Surveiller les renforts et les PV"],"tip":"L'ancienne source décrit un finisseur Crunch. La fin réelle dépend des dégâts et des Pokémon encore présents."}]}],"alerts":["Cette adaptation du mode facile provient d'une stratégie difficile historique (Turtle/Rumel 2023), distincte de la feuille de route Hydreigon proposée en mode difficile sur le site. Le guide dédié facile 2024 est disponible en vidéo.","Les attaques, positions, objets et EV ne sont pas des valeurs 2025 certifiées. Tester et ajuster avant de dépenser un Bonbon Spécial.","Une équipe capable de battre le mode difficile peut aussi être utilisée en facile, mais les PV, les attaques adverses et les objets consommés ne suivent pas forcément le même calendrier."]};
